import sys

def main():
    data = sys.stdin.read().split()
    n, m = int(data[0]), int(data[1])
    parent = list(range(n))

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        while parent[x] != root:
            parent[x], x = root, parent[x]
        return root

    us = data[2:2 + 2 * m:2]
    vs = data[3:3 + 2 * m:2]
    for a, b in zip(us, vs):
        ra, rb = find(int(a)), find(int(b))
        if ra != rb:
            parent[ra] = rb
    size = [0] * n
    edges = [0] * n
    for v in range(n):
        size[find(v)] += 1
    for a in us:
        edges[find(int(a))] += 1
    ans = 0
    for v in range(n):
        if parent[v] == v and edges[v] == size[v] * (size[v] - 1) // 2:
            ans += 1
    print(ans)

main()

